'use strict';
let referenceSubsection='Foundation';
function findReferenceSite(){showModal('Find a site',`<form onsubmit="event.preventDefault();closeModal();globalSearch(document.getElementById('reference-find').value)"><div class="field"><label for="reference-find">Site ID or project</label><input id="reference-find" placeholder="Find a site…" required></div><button class="btn primary" type="submit">Find site</button></form>`);}
function showModuleMenu(){showModal('More workspace modules',`<div class="extra-modules">${[['overview','My work'],['photos','Photo library'],['map','Network map'],['projects','Projects'],['team','Team & roles']].map(([v,n])=>`<button class="btn" onclick="closeModal();go('${v}')">${E(n)}${I('arrow')}</button>`).join('')}</div>`);}
const referenceBaseRole=changeRole;
changeRole=function(r){referenceBaseRole(r);if(r!=='Engineer'){view='workspace';selected=data.sites.find(s=>s.status==='Awaiting review')?.id||data.sites[0].id;section='civil';customSection=0;workTab='photos';referenceSubsection='Foundation';catalogOpen=true;render();}};
function referencePick(id,label){section=id;referenceSubsection=label;workTab='photos';viewerIndex=0;render();}
function referenceViewSubmission(){workTab='checklist';section='submission';customSection=reviewSections().length;render();}
const templateCatalog=catalog;
catalog=function(){const s=site();if(s.templateSnapshot)return templateCatalog();const selectedLeaf=(id,name)=>`<button class="catalog-item reference-leaf ${section===id&&referenceSubsection===name?'active':''}" onclick="referencePick('${id}','${name}')">${I('file')}<span>${name}</span>${sectionLocked(id)?I('shield'):''}</button>`;const leafMatches=name=>!catalogQuery||name.toLowerCase().includes(catalogQuery.toLowerCase());const group=(title,rows)=>`<details class="catalog-group reference-branch" open><summary>${I('folder')}${title}</summary>${rows.filter(([id,label])=>leafMatches(label)||leafMatches(title)).map(([id,label])=>selectedLeaf(id,label)).join('')}</details>`;return `<aside class="catalog ${catalogOpen?'':'catalog-hidden'}"><div class="catalog-heading"><h2>Site catalog</h2></div><div class="project-tree"><details open><summary>${I('folder')}${E(s.project)}</summary><details open><summary>${I('folder')}${E(s.subproject||s.region||'Riyadh region')}</summary><select aria-label="Select Site ID" onchange="openSite(this.value)">${visibleSites().filter(x=>x.project===s.project).map(x=>`<option ${x.id===s.id?'selected':''}>${E(x.id)}</option>`).join('')}</select></details></details></div><form class="catalog-search" onsubmit="event.preventDefault();catalogQuery=this.querySelector('input').value;render()">${I('search')}<input aria-label="Find section" placeholder="Find section…" value="${E(catalogQuery)}"><button type="submit" aria-label="Search sections">${I('arrow')}</button></form><div class="catalog-tools"><button class="${catalogGrouped?'chosen':''}" onclick="catalogGrouped=true;render()">${I('folder')}Group</button><button class="${!catalogGrouped?'chosen':''}" onclick="catalogGrouped=false;render()">${I('folder')}Ungroup</button></div><nav aria-label="Checklist sections">${catalogGrouped?`<button class="catalog-item reference-parent ${section==='general'?'active':''}" onclick="referencePick('general','Site details')">${I('down')}${I('file')}Site details</button><details open class="catalog-group reference-root"><summary>${I('folder')}Checklist</summary>${group('Civil & site',[['civil','Foundation'],['civil','Tower condition'],['civil','Site access']])}${group('Power systems',[['power','Utility supply'],['power','DG / SG'],['power','Solar'],['power','DC power']])}${group('Electrical & grounding',[['electrical','Electrical readings'],['electrical','Grounding']])}</details><details class="catalog-group"><summary>${I('folder')}Tower equipment</summary>${selectedLeaf('equipment','Equipment inventory')}</details>`:reviewSections().filter(x=>leafMatches(x.title)).map(x=>`<button class="catalog-item ${section===x.id?'active':''}" onclick="referencePick('${x.id}','${E(x.title)}')">${I('file')}<span>${E(x.title)}</span></button>`).join('')}<button class="catalog-item reference-parent ${section==='evidence'?'active':''}" onclick="referencePick('evidence','Photos')">${I('chevron')}${I('camera')}Photos</button><button class="catalog-item reference-parent" onclick="referenceViewSubmission()">${I('chevron')}${I('clipboard')}Review & approval</button></nav></aside>`;};
decisionPanel=function(){const s=site(),canReview=['Awaiting review','Under Review','Partially approved'].includes(s.status),count=[...reviewSelection].filter(id=>reviewSections().some(x=>x.id===id)&&!sectionLocked(id)).length;if(role==='Engineer')return '';return `<section class="decision-panel reference-approval" aria-label="Survey review decision"><div class="decision-top"><label class="observation">Observation<textarea aria-label="Review observation" placeholder="Add an observation…" oninput="reviewNote=this.value">${E(reviewNote)}</textarea></label><div><strong>Request changes</strong><button class="btn" ${canReview?'':'disabled'} onclick="recordWorkspaceDecision('changes')">Request changes</button></div><div class="decision-options"><strong>Review decision</strong><div>${[['approve','Full Approve'],['partial','Partial Approve'],['reject','Full Reject']].map(([mode,label])=>`<button class="btn ${mode} ${decisionMode===mode?'selected':''}" aria-pressed="${decisionMode===mode}" onclick="pickDecision('${mode}')">${decisionMode===mode?I('check'):''}${label}</button>`).join('')}</div></div></div>${decisionMode==='partial'?`<div class="section-selector"><div class="reference-select-title"><strong>Select sections to approve (Partial Approve)</strong><div class="reference-select-actions"><button class="text-action" onclick="selectReviewAll(true)">Select all</button><button class="text-action" onclick="selectReviewAll(false)">Clear selection</button><span>${count} sections selected</span></div><button class="btn primary" ${canReview?'':'disabled'} onclick="recordWorkspaceDecision('partial')">Approve selected sections</button></div><div class="section-choices">${reviewSections().map(x=>`<label><input type="checkbox" ${sectionLocked(x.id)?'disabled checked':reviewSelection.has(x.id)?'checked':''} onchange="selectReviewSection('${E(x.id)}',this.checked)"><span>${E(x.title)}</span>${sectionLocked(x.id)?I('shield'):''}</label>`).join('')}</div><p class="reference-approval-note">${canReview?'Approved sections locked · Remaining sections pending':'Submit the survey to enable review'}</p></div>`:`<div class="reference-decision-confirm"><span>${decisionMode==='reject'?'A rejection reason is required.':'Approve all applicable survey sections.'}</span><button class="btn ${decisionMode==='reject'?'danger':'primary'}" ${canReview?'':'disabled'} onclick="recordWorkspaceDecision(decisionMode)">${decisionMode==='reject'?'Confirm full rejection':'Confirm full approval'}</button></div>`}</section>`;};
// Keep the photo viewer and checklist switch together, without another navigation row.
const referencePhotos=workspacePhotos;
workspacePhotos=function(){const sec=reviewSections().find(x=>x.id===currentSectionId()),name=site().templateSnapshot?sec?.title:section==='civil'?'Civil & site / '+referenceSubsection:section==='power'?'Power systems / '+referenceSubsection:sec?.title;let h=referencePhotos();const start=h.indexOf('<h2>'),end=h.indexOf('</h2>',start);if(start>=0)h=h.slice(0,start)+'<h2>'+E(name||'Site photographs')+h.slice(end);h=h.replace('<p>Illustrative image · upload your own section evidence</p>','<p>Photo evidence <small>· Demonstration image until photos are uploaded</small></p>');h=h.replace('<button class="btn"',`<button class="btn reference-form-toggle" onclick="setWorkTab('checklist')">${I('clipboard')}Checklist</button><button class="btn"`);if(!site().photos.some(p=>photoSection(p)===currentSectionId()||currentSectionId()==='evidence')){h=h.replace('<div class="photo-strip">','<div class="photo-strip"><button class="active demo-thumb" aria-label="Demonstration photo"><img src="assets/towers.jpg" alt="Demonstration telecom photo"></button>');}return h;};
workspacePage=function(){const s=site();return `<div class="workspace-heading reference-site-heading"><div class="row wrap"><h1>${E(s.id)}</h1>${badge(s.status)}<span class="small muted">${s.progress}%</span></div><button class="iconbtn" aria-label="Export site record" onclick="downloadReport('${E(s.id)}')">${I('export')}</button></div>${s.templateSnapshot?`<div class="workspace-branding">${clientLogos(s.templateSnapshot.clients)}<span>${E(s.templateSnapshot.name)} · v${s.templateSnapshot.version}</span></div>`:''}${decisionPanel()}${workTab==='photos'?workspacePhotos():`<div class="reference-checklist-return"><button class="btn" onclick="setWorkTab('photos')">${I('camera')}Back to photos</button></div>${workspaceChecklist()}`}`;};
render();
